/* ============================================================================
   argento — design tokens
   ----------------------------------------------------------------------------
   Palette: gruvbox dark (bright accents) / gruvbox light (faded accents).
   Everything downstream (pico-map.css, components.css, your apps) reads only
   the semantic `--argento-*` tokens below, never the raw palette. Retheme by
   editing this file alone, then run `npm run check`.
   ========================================================================== */

:root {
  /* ── Raw palette: gruvbox greys ───────────────────────────────────────── */
  --argento-gb-dark0-hard: #1d2021;
  --argento-gb-dark0: #282828;
  --argento-gb-dark0-soft: #32302f;
  --argento-gb-dark1: #3c3836;
  --argento-gb-dark2: #504945;
  --argento-gb-dark3: #665c54;
  --argento-gb-dark4: #7c6f64;
  --argento-gb-gray: #928374;
  --argento-gb-light4: #a89984;
  --argento-gb-light3: #bdae93;
  --argento-gb-light2: #d5c4a1;
  --argento-gb-light1: #ebdbb2;
  --argento-gb-light0: #fbf1c7;
  --argento-gb-light0-hard: #f9f5d7;
  --argento-gb-light0-soft: #f2e5bc;

  /* ── Raw palette: gruvbox bright (for dark backgrounds) ───────────────── */
  /* bright-red is gruvbox's #fb4934 lifted to clear 4.5:1 on dark0-soft; the
     original only reaches 3.8:1, which fails for `danger` body text. */
  --argento-gb-bright-red: #fb6a51;
  --argento-gb-bright-green: #b8bb26;
  --argento-gb-bright-yellow: #fabd2f;
  --argento-gb-bright-blue: #83a598;
  --argento-gb-bright-purple: #d3869b;
  --argento-gb-bright-aqua: #8ec07c;
  --argento-gb-bright-orange: #fe8019;

  /* ── Raw palette: gruvbox faded (for light backgrounds) ───────────────── */
  /* faded-yellow (#b57614), faded-green (#79740e) and faded-aqua (#427b58) are
     likewise deepened; a yellow dark enough for AA on gruvbox light
     necessarily reads as ochre. */
  --argento-gb-faded-red: #9d0006;
  --argento-gb-faded-green: #757011;
  --argento-gb-faded-yellow: #92641e;
  --argento-gb-faded-blue: #076678;
  --argento-gb-faded-purple: #8f3f71;
  --argento-gb-faded-aqua: #427857;
  --argento-gb-faded-orange: #af3a03;

  /* ── Shape, motion, density ───────────────────────────────────────────── */
  --argento-radius: 0.375rem;
  --argento-radius-sm: 0.25rem;
  --argento-radius-lg: 0.75rem;
  --argento-border-width: 1px;
  --argento-outline-width: 2px;
  --argento-spacing: 1rem;
  --argento-spacing-sm: 0.5rem;
  --argento-spacing-lg: 1.5rem;
  --argento-transition: 0.12s ease-in-out;

  /* ── Typography ───────────────────────────────────────────────────────── */
  /* Iosevka throughout — UI, headings and numbers are one family. Weight, size
     and color carry the hierarchy: nothing is set in all caps, and nothing
     relies on small caps, which this build of Iosevka does not have. The emoji
     faces are last so that pictographs Iosevka has no business drawing
     (📸, 💾, ⚠️) reach the system color font instead of falling out as tofu. */
  --argento-font-emoji: "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji";
  --argento-font-sans: "Iosevka", ui-monospace, SFMono-Regular, "SF Mono", Menlo,
    Consolas, "Liberation Mono", monospace, var(--argento-font-emoji);
  --argento-font-mono: var(--argento-font-sans);
  /* Headings only. Iosevka Extended is the same typeface 20% wider, which
     gives headings presence without a second typeface or a color change.
     Anything Extended lacks falls through to regular Iosevka. */
  --argento-font-display: "Iosevka Extended", var(--argento-font-sans);
  --argento-font-size: 100%;
  --argento-line-height: 1.55;

  --argento-font-weight: 300;
  --argento-font-weight-display: 200;
  --argento-font-weight-heading: 300;
  --argento-font-weight-label: 500;
  --argento-font-weight-strong: 600;
  --argento-letter-spacing-heading: -0.005em;
}

/* ── Semantic tokens: LIGHT ─────────────────────────────────────────────── */
:root:not([data-theme="dark"]),
[data-theme="light"] {
  color-scheme: light;

  --argento-bg: var(--argento-gb-light0);
  --argento-surface: var(--argento-gb-light0-hard);
  --argento-surface-sunk: var(--argento-gb-light0-soft);
  --argento-surface-raised: var(--argento-gb-light0-hard);
  --argento-overlay: rgb(60 56 54 / 45%);

  --argento-border: var(--argento-gb-light2);
  --argento-border-dim: var(--argento-gb-light1);

  /* Filled neutral controls (secondary buttons, switch tracks, thumbs). */
  --argento-neutral: var(--argento-gb-dark3);
  --argento-on-neutral: var(--argento-gb-light0);
  /* Background of text inputs, selects and textareas. */
  --argento-field: var(--argento-gb-light0-hard);

  --argento-text: var(--argento-gb-dark1);
  --argento-text-muted: var(--argento-gb-dark2);
  --argento-text-subtle: var(--argento-gb-dark3);
  --argento-text-inverse: var(--argento-gb-light0);

  --argento-red: var(--argento-gb-faded-red);
  --argento-orange: var(--argento-gb-faded-orange);
  --argento-yellow: var(--argento-gb-faded-yellow);
  --argento-green: var(--argento-gb-faded-green);
  --argento-aqua: var(--argento-gb-faded-aqua);
  --argento-blue: var(--argento-gb-faded-blue);
  --argento-purple: var(--argento-gb-faded-purple);

  /* Text drawn on top of an accent-filled surface. */
  --argento-on-accent: var(--argento-gb-light0);

  --argento-shadow: 0 1px 2px rgb(60 56 54 / 8%), 0 4px 12px rgb(60 56 54 / 10%);
}

/* ── Semantic tokens: DARK ──────────────────────────────────────────────── */
@media only screen and (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;

    --argento-bg: var(--argento-gb-dark0);
    --argento-surface: var(--argento-gb-dark0-soft);
    --argento-surface-sunk: var(--argento-gb-dark0-hard);
    --argento-surface-raised: var(--argento-gb-dark1);
    --argento-overlay: rgb(29 32 33 / 65%);

    --argento-border: var(--argento-gb-dark2);
    --argento-border-dim: var(--argento-gb-dark1);

    --argento-neutral: var(--argento-gb-dark3);
    --argento-on-neutral: var(--argento-gb-light0);
    --argento-field: var(--argento-gb-dark0-hard);

    --argento-text: var(--argento-gb-light1);
    --argento-text-muted: var(--argento-gb-light2);
