     `:root { --argento-accent: var(--argento-orange); }` */
  --argento-accent: var(--argento-aqua);
  --argento-accent-hover: color-mix(in srgb, var(--argento-accent) 80%, var(--argento-text));
  --argento-accent-wash: color-mix(in srgb, var(--argento-accent) 14%, transparent);
  --argento-accent-ring: color-mix(in srgb, var(--argento-accent) 40%, transparent);

  --argento-success: var(--argento-green);
  --argento-warning: var(--argento-orange);
  --argento-danger: var(--argento-red);
