     adjacent entries stay distinguishable in both themes. */
  --argento-viz-1: var(--argento-blue);
  --argento-viz-2: var(--argento-orange);
  --argento-viz-3: var(--argento-green);
  --argento-viz-4: var(--argento-purple);
  --argento-viz-5: var(--argento-aqua);
  --argento-viz-6: var(--argento-red);
