  /* Lightened past tokyonight.nvim's own "comment", which is deliberately
     low-contrast in an editor gutter, not AA body text on a dark page. */
  --argento-tn-comment: #8c95c4;
  --argento-tn-fg-dark: #a9b1d6;
  --argento-tn-fg: #c0caf5;

  /* ── Raw palette: Tokyo Night accents (bright, for dark backgrounds) ───── */
  --argento-tn-red: #f7768e;
  --argento-tn-orange: #ff9e64;
  --argento-tn-yellow: #e0af68;
  --argento-tn-green: #9ece6a;
