  --argento-td-comment: #4c5480;
  --argento-td-fg-dark: #46519a;
  --argento-td-fg: #3760bf;

  /* ── Raw palette: Tokyo Day accents (deepened, for light backgrounds) ──── */
  --argento-td-red: #a83a3a;
  --argento-td-orange: #8f4b00;
  --argento-td-yellow: #6e5527;
  --argento-td-green: #4a6130;
  --argento-td-cyan: #065f7d;
  --argento-td-blue: #1a4a8f;
  --argento-td-magenta: #6a3aa8;
