/* ============================================================================
   argento — Pico CSS variable mapping
   ----------------------------------------------------------------------------
   Translates the semantic `--argento-*` tokens into the `--pico-*` variables
   Pico reads. Nothing here should contain a literal color.

   The `:root:root:root` selector is deliberate: Pico's own color-scheme rules
   use `:root:not([data-theme=light])` (specificity 0,2,0), so a plain `:root`
   block would lose to them even though it loads later.
   ========================================================================== */

:root:root:root {
  /* ── Surfaces & text ───────────────────────────────────────────────────── */
  --pico-background-color: var(--argento-bg);
  --pico-color: var(--argento-text);
  --pico-h1-color: var(--argento-text);
  --pico-h2-color: var(--argento-text);
  --pico-h3-color: var(--argento-text);
  --pico-h4-color: var(--argento-text);
  /* No heading is dimmer than the body text or form labels beneath it, so the
     color ramp stops here and size and weight carry the rest. */
  --pico-h5-color: var(--argento-text);
  --pico-h6-color: var(--argento-text);
  --pico-muted-color: var(--argento-text-subtle);
  --pico-muted-border-color: var(--argento-border-dim);
  --pico-border-color: var(--argento-border);
  --pico-text-selection-color: color-mix(in srgb, var(--argento-accent) 28%, transparent);
  --pico-box-shadow: var(--argento-shadow);

  /* ── Primary = brand accent ────────────────────────────────────────────── */
  --pico-primary: var(--argento-accent);
  --pico-primary-background: var(--argento-accent);
  --pico-primary-border: var(--argento-accent);
  --pico-primary-underline: color-mix(in srgb, var(--argento-accent) 50%, transparent);
  --pico-primary-hover: var(--argento-accent-hover);
  --pico-primary-hover-background: var(--argento-accent-hover);
  --pico-primary-hover-border: var(--argento-accent-hover);
  --pico-primary-hover-underline: var(--argento-accent-hover);
  --pico-primary-focus: var(--argento-accent-ring);
  --pico-primary-inverse: var(--argento-on-accent);

  /* ── Secondary = neutral fill ──────────────────────────────────────────── */
  --pico-secondary: var(--argento-text-muted);
  --pico-secondary-background: var(--argento-neutral);
  --pico-secondary-border: var(--argento-neutral);
  --pico-secondary-underline: color-mix(in srgb, var(--argento-text-muted) 50%, transparent);
  --pico-secondary-hover: var(--argento-text);
  --pico-secondary-hover-background: color-mix(in srgb, var(--argento-neutral) 75%, var(--argento-text));
  --pico-secondary-hover-border: color-mix(in srgb, var(--argento-neutral) 75%, var(--argento-text));
  --pico-secondary-hover-underline: var(--argento-text);
  --pico-secondary-focus: color-mix(in srgb, var(--argento-neutral) 40%, transparent);
  --pico-secondary-inverse: var(--argento-on-neutral);

  /* ── Contrast = maximum-weight action ──────────────────────────────────── */
  --pico-contrast: var(--argento-text);
  --pico-contrast-background: var(--argento-text);
  --pico-contrast-border: var(--argento-text);
  --pico-contrast-underline: color-mix(in srgb, var(--argento-text) 50%, transparent);
  --pico-contrast-hover: var(--argento-text);
  --pico-contrast-hover-background: color-mix(in srgb, var(--argento-text) 85%, var(--argento-bg));
  --pico-contrast-hover-border: color-mix(in srgb, var(--argento-text) 85%, var(--argento-bg));
  --pico-contrast-hover-underline: var(--argento-text);
  --pico-contrast-focus: color-mix(in srgb, var(--argento-text) 25%, transparent);
  --pico-contrast-inverse: var(--argento-bg);

  /* ── Form elements ─────────────────────────────────────────────────────── */
  --pico-form-element-background-color: var(--argento-field);
  --pico-form-element-border-color: var(--argento-border);
  --pico-form-element-color: var(--argento-text);
  --pico-form-element-placeholder-color: var(--argento-text-subtle);
  --pico-form-element-active-background-color: var(--argento-field);
  --pico-form-element-active-border-color: var(--argento-accent);
  --pico-form-element-focus-color: var(--argento-accent);
  /* Only used for <select multiple> option:checked, where the option's own text
     color is not ours to set — so tint rather than fill. */
  --pico-form-element-selected-background-color: color-mix(in srgb, var(--argento-accent) 30%, var(--argento-field));
  --pico-form-element-disabled-opacity: 0.45;
  --pico-form-element-invalid-border-color: var(--argento-danger);
  --pico-form-element-invalid-active-border-color: var(--argento-danger);
  --pico-form-element-invalid-focus-color: var(--argento-danger);
  --pico-form-element-valid-border-color: var(--argento-success);
  --pico-form-element-valid-active-border-color: var(--argento-success);
  --pico-form-element-valid-focus-color: var(--argento-success);
  --pico-form-label-font-weight: var(--argento-font-weight-label);

  /* ── Switch & range ────────────────────────────────────────────────────── */
  --pico-switch-background-color: var(--argento-neutral);
  --pico-switch-checked-background-color: var(--argento-accent);
  --pico-switch-color: var(--argento-on-neutral);
  --pico-switch-thumb-box-shadow: 0 0 0 rgb(0 0 0 / 0%);
  --pico-range-border-color: var(--argento-border-dim);
  --pico-range-active-border-color: var(--argento-border);
  --pico-range-thumb-border-color: var(--argento-bg);
  --pico-range-thumb-color: var(--argento-accent);
  --pico-range-thumb-active-color: var(--argento-accent-hover);

  /* ── Card ──────────────────────────────────────────────────────────────── */
  --pico-card-background-color: var(--argento-surface);
  --pico-card-border-color: var(--argento-border-dim);
  --pico-card-box-shadow: var(--argento-shadow);
  --pico-card-sectioning-background-color: var(--argento-surface-sunk);

  /* ── Dropdown / accordion / details ────────────────────────────────────── */
  --pico-dropdown-background-color: var(--argento-surface);
  --pico-dropdown-border-color: var(--argento-border);
  --pico-dropdown-color: var(--argento-text);
  --pico-dropdown-hover-background-color: var(--argento-accent-wash);
  --pico-dropdown-box-shadow: var(--argento-shadow);
  --pico-accordion-border-color: var(--argento-border-dim);
  --pico-accordion-close-summary-color: var(--argento-text);
  --pico-accordion-open-summary-color: var(--argento-text-muted);
  --pico-accordion-active-summary-color: var(--argento-accent);

  /* ── Tables, progress, tooltip, modal ──────────────────────────────────── */
  --pico-table-border-color: var(--argento-border-dim);
  --pico-table-row-stripped-background-color: color-mix(in srgb, var(--argento-text) 4%, transparent);
  --pico-progress-background-color: var(--argento-border-dim);
  --pico-progress-color: var(--argento-accent);
  --pico-tooltip-background-color: var(--argento-text);
  --pico-tooltip-color: var(--argento-bg);
  --pico-modal-overlay-background-color: var(--argento-overlay);
  --pico-loading-spinner-opacity: 0.6;

  /* ── Inline content ────────────────────────────────────────────────────── */
  --pico-code-background-color: var(--argento-surface-sunk);
  --pico-code-color: var(--argento-text-muted);
  --pico-code-kbd-background-color: var(--argento-text);
  --pico-code-kbd-color: var(--argento-bg);
  --pico-mark-background-color: var(--argento-accent-wash);
  --pico-mark-color: var(--argento-text);
  --pico-ins-color: var(--argento-success);
  --pico-del-color: var(--argento-danger);
  --pico-blockquote-border-color: var(--argento-border-dim);
  --pico-blockquote-footer-color: var(--argento-text-subtle);

  /* ── Typography, shape, density ────────────────────────────────────────── */
  --pico-font-family-sans-serif: var(--argento-font-sans);
  --pico-font-family-monospace: var(--argento-font-mono);
  --pico-font-family: var(--argento-font-sans);
  --pico-font-size: var(--argento-font-size);
  --pico-line-height: var(--argento-line-height);
  --pico-font-weight: var(--argento-font-weight);
  --pico-border-radius: var(--argento-radius);
  --pico-border-width: var(--argento-border-width);
  --pico-outline-width: var(--argento-outline-width);
  --pico-spacing: var(--argento-spacing);
  --pico-typography-spacing-vertical: var(--argento-spacing);
  --pico-form-element-spacing-vertical: 0.55rem;
  --pico-form-element-spacing-horizontal: 0.85rem;
  --pico-transition: var(--argento-transition);
  --pico-text-underline-offset: 0.14em;
  --pico-button-box-shadow: none;
  --pico-button-hover-box-shadow: none;
}

